CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE COLLATE NOCASE,
  password_hash TEXT NOT NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL
);
CREATE INDEX sessions_user_id ON sessions(user_id);

-- Ids are generated by the client (crypto.randomUUID) and are unique per user.
CREATE TABLE characters (
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  id         TEXT NOT NULL,
  name       TEXT NOT NULL,
  classes    TEXT NOT NULL DEFAULT '[]', -- JSON array of class names
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, id)
);

CREATE TABLE character_favorite_spells (
  user_id      TEXT NOT NULL,
  character_id TEXT NOT NULL,
  spell_index  TEXT NOT NULL,
  PRIMARY KEY (user_id, character_id, spell_index),
  FOREIGN KEY (user_id, character_id) REFERENCES characters(user_id, id) ON DELETE CASCADE
);

CREATE TABLE character_favorite_wild_shapes (
  user_id        TEXT NOT NULL,
  character_id   TEXT NOT NULL,
  wild_shape_key TEXT NOT NULL,
  PRIMARY KEY (user_id, character_id, wild_shape_key),
  FOREIGN KEY (user_id, character_id) REFERENCES characters(user_id, id) ON DELETE CASCADE
);

CREATE TABLE custom_spells (
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  id         TEXT NOT NULL, -- the spell "index"
  name       TEXT NOT NULL,
  level      INTEGER NOT NULL,
  data       TEXT NOT NULL, -- JSON of CustomSpellInput
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, id)
);

CREATE TABLE custom_wild_shapes (
  user_id          TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  id               TEXT NOT NULL, -- the wild shape "key"
  name             TEXT NOT NULL,
  challenge_rating REAL NOT NULL,
  data             TEXT NOT NULL, -- JSON of CustomWildShapeInput
  created_at       TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at       TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, id)
);

CREATE TABLE card_texts (
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  spell_index TEXT NOT NULL,
  text        TEXT NOT NULL,
  PRIMARY KEY (user_id, spell_index)
);
